public async Task HandleAsync(Message message, CancellationToken ct)
{
    await using var tx = await _db.Database.BeginTransactionAsync(ct);
    var raw = await _db.LockEventAsync(message.EventId, skipLocked: true, ct);
    if (raw is null || raw.Status == EventStatus.Done)
    {
        await tx.CommitAsync(ct);
        await _bus.AckAsync(message, ct);
        return;
    }

    await _db.UpsertInternalRecordAsync(raw.IdempotencyKey, raw.Payload, ct); // ON CONFLICT (idempotency_key) DO UPDATE
    await _db.InsertOutboxAsync(raw.IdempotencyKey, new RecordCreated(raw.IdempotencyKey), ct); // ON CONFLICT DO NOTHING
    raw.MarkDone();
    await _db.SaveChangesAsync(ct);
    await tx.CommitAsync(ct);
    await _bus.AckAsync(message, ct);
}
